 local guid=self.character:GetValue()or UnitGUID("player");local accountUUID=guid and(HolyStorm.TwinkCore:GetAccountUUIDForCharacter(guid)or HolyStorm.Data.PlayerStore:GetCharacterOwner(guid));local permission=self.permission:GetText();local explanation=Engine:Explain(permission,accountUUID,guid,self.target:GetText());local state=State:GetPermissionStateStatus();local actor=state.changedBy and table.concat({state.changedBy.accountUUID or"-",state.changedBy.characterUUID or"-"}," / ")or"-";local missing=state.missingRevisions and tostring(state.missingRevisions.after or"-").." -> "..tostring(state.missingRevisions.target or"-")or"-";local fork=state.fork and tostring(state.fork.localRevision or"-").." <> "..tostring(state.fork.remoteRevision or"-")or"-";local lines={L["IDENTITY"],L["CHARACTER"]..": "..tostring(guid),L["ACCOUNT_MEMBERS"]..": "..tostring(accountUUID),"",string.format(L["STATE_DETAILS_FORMAT"],tostring(state.guildId or"-"),L["STATE_"..tostring(state.status)]or tostring(state.status),state.version or 0,tostring(state.revisionID or"-"),tostring(state.previousRevisionID or"-"),displayTime(state.lastSync),actor,displayTime(state.changedAt),state.historyLength or 0,state.rejectedLength or 0,missing,fork),L["RESULT"]..": "..(explanation.allowed and L["ALLOWED"]or L["DENIED"]),"",L["EFFECTIVE_MEMBERS"]}
