 lines[#lines+1]="";lines[#lines+1]=L["REVISION_HISTORY"];for _,revision in ipairs(State:GetRevisionHistory())do lines[#lines+1]=string.format("v%d | %s | %s | %s | %s",revision.version or 0,tostring(revision.revisionID),tostring(revision.previousRevisionID),tostring(revision.action or(revision.change and revision.change.action)),displayTime(revision.changedAt))end
